kata.solucion:
type Desenvuelto<T> = T extends (infer U)[] ? U | null : T;

export function desenvolver<T>(valor: T): Desenvuelto<T> {
  if (Array.isArray(valor)) return (valor.length ? valor[0] : null) as Desenvuelto<T>;
  return valor as Desenvuelto<T>;
}
